<?php
namespace App\Http\Controllers\Mentor;
use App\Http\Controllers\Controller; use App\Models\Certificate; use App\Models\Enrollment; use App\Models\Exam; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class ExamController extends Controller {
 public function storeAttempt(Request $r){$d=$r->validate(['exam_id'=>'required|exists:exams,id','enrollment_id'=>'required|exists:enrollments,id','score'=>'required|integer|min:0|max:100','mentor_feedback'=>'nullable|max:2000']);$exam=Exam::with('course')->findOrFail($d['exam_id']);abort_unless($exam->course->instructor_id===$r->user()->id,403);$enrollment=Enrollment::findOrFail($d['enrollment_id']);abort_unless($enrollment->course_id===$exam->course_id,422);$attempts=$enrollment->examAttempts()->where('exam_id',$exam->id)->count();if($attempts >= $exam->max_attempts)throw ValidationException::withMessages(['score'=>'Batas percobaan ujian sudah tercapai.']);$passed=$d['score'] >= $exam->passing_score;DB::transaction(function()use($d,$exam,$enrollment,$attempts,$passed){$attempt=$enrollment->examAttempts()->create(['exam_id'=>$exam->id,'attempt_no'=>$attempts+1,'score'=>$d['score'],'status'=>$passed?'passed':'failed','mentor_feedback'=>$d['mentor_feedback']??null,'taken_at'=>now()]);if($passed){Certificate::firstOrCreate(['enrollment_id'=>$enrollment->id],['exam_attempt_id'=>$attempt->id,'certificate_no'=>'CERT-SP-'.now()->format('Ym').'-'.strtoupper(Str::random(8)),'issued_at'=>now()]);$enrollment->update(['final_status'=>'passed','status'=>'completed','progress'=>100,'completed_at'=>now()]);}});return back()->with('success',$passed?'Ujian lulus. Sertifikat otomatis diterbitkan.':'Nilai tersimpan. Peserta dapat retake jika masih memiliki kesempatan.');}
}
